const setContactLeadOfAttempt = `-- name: SetContactLeadOfAttempt :execrows
UPDATE campaign_contacts
SET lead_intent = $2, updated_at = now()
WHERE id = $1 AND last_attempt_id = $3::uuid
`

type SetContactLeadOfAttemptParams struct {
	ID         uuid.UUID `json:"id"`
	LeadIntent *string   `json:"leadIntent"`
	AttemptID  uuid.UUID `json:"attemptId"`
}

// A verdict moves the contact's lead only while this attempt is still the
// contact's latest: a later call has settled the contact since, and its lead
// (or the lead it kept) is not this call's to change.
func (q *Queries) SetContactLeadOfAttempt(ctx context.Context, arg SetContactLeadOfAttemptParams) (int64, error) {
	result, err := q.db.Exec(ctx, setContactLeadOfAttempt, arg.ID, arg.LeadIntent, arg.AttemptID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const settleCampaignContact = `-- name: SettleCampaignContact :exec
UPDATE campaign_contacts
SET attempts = $2, system_failures = $3, status = $4, next_attempt_at = $5,
    retry_at = $7::timestamptz, is_frequency_held = false, is_daily_cap_held = false,
    last_outcome = $6, last_attempt_id = $8::uuid,
    last_call_id = $9::uuid,
    lead_intent = coalesce($10::text, lead_intent),
    lead_notes = CASE WHEN $10::text IS NULL THEN lead_notes
                      ELSE $11::text END,
    updated_at = now()
WHERE id = $1
`

type SettleCampaignContactParams struct {
	ID             uuid.UUID          `json:"id"`
	Attempts       int32              `json:"attempts"`
	SystemFailures int32              `json:"systemFailures"`
	Status         string             `json:"status"`
	NextAttemptAt  pgtype.Timestamptz `json:"nextAttemptAt"`
	LastOutcome    *string            `json:"lastOutcome"`
	RetryAt        pgtype.Timestamptz `json:"retryAt"`
	LastAttemptID  uuid.UUID          `json:"lastAttemptId"`
	LastCallID     uuid.UUID          `json:"lastCallId"`
	LeadIntent     *string            `json:"leadIntent"`
	LeadNotes      *string            `json:"leadNotes"`
}

// The contact after its latest attempt settled: counters, fate and schedule.
// retry_at is the time the retry policy gave, before the calling window moved
// it into next_attempt_at; both are NULL unless the contact stays ACTIVE.
// A recorded lead is kept (copied only when this attempt recorded one); the
// last attempt and its call are always this one, so after a retry that
// recorded no lead they name a later call than the lead's.
func (q *Queries) SettleCampaignContact(ctx context.Context, arg SettleCampaignContactParams) error {
	_, err := q.db.Exec(ctx, settleCampaignContact,
		arg.ID,
		arg.Attempts,
		arg.SystemFailures,
		arg.Status,
		arg.NextAttemptAt,
		arg.LastOutcome,
		arg.RetryAt,
		arg.LastAttemptID,
		arg.LastCallID,
		arg.LeadIntent,
		arg.LeadNotes,
	)
	return err
}

const settleLeadVerdict = `-- name: SettleLeadVerdict :one
UPDATE campaign_attempts
SET lead_verdict = $2, lead_verdict_reason = $3,
    lead_intent = $4
WHERE id = $1 AND lead_verdict = 'PENDING' AND lead_judge_deadline_at > now()
RETURNING id, campaign_id, campaign_contact_id, number_e164, call_id, leg_id, originate_job_id, state, outcome, hangup_cause, talk_sec, is_touched, lead_intent, lead_notes, started_at, finished_at, is_test_number, declared_lead_intent, lead_verdict, lead_verdict_reason, lead_judge_deadline_at, sip_status
`

type SettleLeadVerdictParams struct {
	ID                uuid.UUID `json:"id"`
	LeadVerdict       *string   `json:"leadVerdict"`
	LeadVerdictReason *string   `json:"leadVerdictReason"`
	LeadIntent        *string   `json:"leadIntent"`
}

// The verdict and the lead it leaves, written only while the judgement is
// still owed and its deadline has not passed: no row back means too late, and
// the verdict is discarded, so the record says what the receiver was sent.
func (q *Queries) SettleLeadVerdict(ctx context.Context, arg SettleLeadVerdictParams) (CampaignAttempt, error) {
	row := q.db.QueryRow(ctx, settleLeadVerdict,
		arg.ID,
		arg.LeadVerdict,
		arg.LeadVerdictReason,
		arg.LeadIntent,
	)
	var i CampaignAttempt
	err := row.Scan(
		&i.ID,
		&i.CampaignID,
		&i.CampaignContactID,
		&i.NumberE164,
		&i.CallID,
		&i.LegID,
		&i.OriginateJobID,
		&i.State,
		&i.Outcome,
		&i.HangupCause,
		&i.TalkSec,
		&i.IsTouched,
		&i.LeadIntent,
		&i.LeadNotes,
		&i.StartedAt,
		&i.FinishedAt,
		&i.IsTestNumber,
		&i.DeclaredLeadIntent,
		&i.LeadVerdict,
		&i.LeadVerdictReason,
		&i.LeadJudgeDeadlineAt,
		&i.SIPStatus,
	)
	return i, err
}
